ALTER TABLE "mcp_servers" ADD COLUMN "catalog_entry_name" text;--> statement-breakpoint
UPDATE "mcp_servers" SET "catalog_entry_name" = "data"->>'catalog_entry_name' WHERE "source" = 'catalog';--> statement-breakpoint
WITH ranked AS (SELECT *, first_value("mcp_server_id") OVER (PARTITION BY "tenant_id","owner_user_id","catalog_entry_name" ORDER BY COALESCE("updated_at","created_at") DESC,"mcp_server_id" DESC) winner FROM "mcp_servers" WHERE "source"='catalog' AND "catalog_entry_name" IS NOT NULL)
INSERT INTO "session_mcp_servers" ("tenant_id","session_id","mcp_server_id","enabled","added_at") SELECT sm."tenant_id",sm."session_id",r.winner,sm."enabled",sm."added_at" FROM "session_mcp_servers" sm JOIN ranked r ON r."mcp_server_id"=sm."mcp_server_id" WHERE r."mcp_server_id"<>r.winner ON CONFLICT DO NOTHING;--> statement-breakpoint
WITH ranked AS (SELECT "mcp_server_id", first_value("mcp_server_id") OVER (PARTITION BY "tenant_id","owner_user_id","catalog_entry_name" ORDER BY COALESCE("updated_at","created_at") DESC,"mcp_server_id" DESC) winner FROM "mcp_servers" WHERE "source"='catalog' AND "catalog_entry_name" IS NOT NULL) DELETE FROM "mcp_servers" USING ranked WHERE "mcp_servers"."mcp_server_id"=ranked."mcp_server_id" AND ranked."mcp_server_id"<>ranked.winner;--> statement-breakpoint
CREATE UNIQUE INDEX "mcp_servers_catalog_owner_uq" ON "mcp_servers" ("tenant_id","owner_user_id","catalog_entry_name") WHERE "source"='catalog' AND "catalog_entry_name" IS NOT NULL;
